"""Build standalone, offline samples-tab direction prototypes from local samples."""
from pathlib import Path
from PIL import Image
import base64
import io
import json

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[2]
OUT = ROOT / 'design-demos'
OUT.mkdir(exist_ok=True)
paths = sorted((REPO / 'training-ui/jobs/@style_neco/output/sample').glob('*.png'))
# Only these inspected, clothed character studies are used in the prototype.
chosen = [paths[i] for i in [0, 1, 2, 3]]
assets = []
for path in chosen:
    im = Image.open(path).convert('RGB')
    size = im.size
    im.thumbnail((1400, 1400))
    stream = io.BytesIO()
    im.save(stream, 'JPEG', quality=87)
    assets.append(dict(src='data:image/jpeg;base64,' + base64.b64encode(stream.getvalue()).decode(),
                       width=size[0], height=size[1], original=path.name))

