JS = r'''
const ASSETS=__ASSETS__;
const MODE=__MODE__;
const icon=(name)=>{const paths={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 5M18 18A8 8 0 0 1 5 13"/>',left:'<path d="m14 5-7 7 7 7"/>',right:'<path d="m10 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v2"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||''}</svg>`};
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const records=Array.from({length:36},(_,i)=>({id:i,asset:ASSETS[[0,1,2,0,1,3][i%6]],epoch:Math.floor(i/6)+1,prompt:i%3,seed:266667, favorite:false}));
let promptFilter=-1, search='', selectMode=false, selected=new Set(), current=0, visible=records.slice();
const gallery=document.querySelector('.gallery-layout'), viewer=document.querySelector('.viewer'), stage=document.querySelector('.stage'), photo=stage.querySelector('img'), inspector=document.querySelector('.inspector');
function label(r){return `E${String(r.epoch).padStart(2,'0')} · P${r.prompt+1}`}
function tile(r){return `<button class="tile ${selected.has(r.id)?'selected':''}" data-id="${r.id}" aria-label="查看 ${label(r)}，${r.asset.width} × ${r.asset.height}"><img src="${r.asset.src}" alt="${['红黑服装角色样例','荧光色服装角色样例','机械翼角色横图'][r.prompt]}" draggable="false"><span class="tick">${selected.has(r.id)?'✓':''}</span><span class="caption"><span>${label(r)}</span><span>${r.asset.width}×${r.asset.height}</span></span></button>`}
function render(){
 visible=records.filter(r=>(promptFilter<0||r.prompt===promptFilter)&&(!search||label(r).toLowerCase().includes(search)||r.asset.original.toLowerCase().includes(search)));
 if(document.querySelector('#sort').value==='new')visible.sort((a,b)=>b.epoch-a.epoch||a.id-b.id);
 const counts=p=>visible.filter(r=>r.prompt===p).length;
 if(MODE==='a')gallery.innerHTML=`<div class="grouped">${[0,1,2].filter(p=>counts(p)).map(p=>`<section><h2 class="section-label"><b>Prompt ${p+1} <span class="muted">${['角色 / 红黑','角色 / 荧光','机械 / 横构图'][p]}</span></b><span>${counts(p)} 张</span></h2><div class="masonry">${visible.filter(r=>r.prompt===p).map(tile).join('')}</div></section>`).join('')}</div>`;
 else if(MODE==='b')gallery.innerHTML=`<aside class="prompt-rail"><h2>提示词分组</h2>${[-1,0,1,2].map(p=>`<button data-filter="${p}" class="${promptFilter===p?'active':''}">${p<0?'全部样例':'Prompt '+(p+1)}<small>${p<0?records.length:12}</small></button>`).join('')}</aside><div><h2 class="section-label"><b>${promptFilter<0?'全部样例':'Prompt '+(promptFilter+1)}</b><span>等格预览 · 点击查看原比例</span></h2><div class="contact-grid">${visible.map(tile).join('')}</div></div>`;
 else{const ps=[0,1,2].filter(p=>counts(p));gallery.innerHTML=`<div class="matrix" style="grid-template-columns:76px repeat(${Math.max(ps.length,1)},minmax(0,1fr))"><div class="col-head">轮次</div>${ps.map(p=>`<div class="col-head">Prompt ${p+1} <small class="muted"> / ${['红黑','荧光','机械翼'][p]}</small></div>`).join('')}${[...new Set(visible.map(r=>r.epoch))].map(e=>`<div class="epoch">E${String(e).padStart(2,'0')}<small>${e*100} 步</small></div>${ps.map(p=>`<div class="cell">${visible.filter(r=>r.epoch===e&&r.prompt===p).map(tile).join('')}</div>`).join('')}`).join('')}</div>`}
 if(!visible.length)gallery.innerHTML='<p class="empty">没有匹配的样例，试试其他文件名或轮次。</p>';
 gallery.classList.toggle('selecting',selectMode);document.querySelector('#count').textContent=`${visible.length} 张样例`;
 document.querySelector('#selection').textContent=selected.size?`已选 ${selected.size} 张`:'点击查看 · Ctrl 多选';
 document.querySelectorAll('[data-filter]').forEach(e=>e.classList.toggle('active',Number(e.dataset.filter)===promptFilter));
 if(MODE==='c'&&innerWidth<=600&&matchMedia('(orientation:portrait)').matches){let m=document.querySelector('.matrix');if(m)m.style.gridTemplateColumns=`45px repeat(${Math.max([0,1,2].filter(p=>counts(p)).length,1)},minmax(0,1fr))`}
}
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){promptFilter=Number(f.dataset.filter);render()}const t=e.target.closest('.tile');if(t){const id=Number(t.dataset.id);if(selectMode||e.ctrlKey||e.metaKey){selected.has(id)?selected.delete(id):selected.add(id);render()}else openImage(id)}});
document.querySelector('#search').addEventListener('input',e=>{search=e.target.value.trim().toLowerCase();render()});document.querySelector('#sort').addEventListener('change',render);
document.querySelector('#density').addEventListener('input',e=>{document.body.style.setProperty('--tile',e.target.value+'px');document.querySelectorAll('.masonry').forEach(el=>el.style.columns=e.target.value+'px')});
document.querySelector('#select').onclick=()=>{selectMode=!selectMode;document.querySelector('#select').classList.toggle('active',selectMode);render()};
document.querySelector('#refresh').onclick=()=>{render();toast('原型演示：图库已刷新')};document.querySelector('#fill').onclick=e=>{document.body.classList.toggle('cover');e.currentTarget.classList.toggle('active');e.currentTarget.textContent=document.body.classList.contains('cover')?'裁切填充':'完整缩略图'};
let scale=1, fit=1, px=0, py=0, drag=null, lastFocus=null, observer;
function paint(){photo.style.width=photo.naturalWidth+'px';photo.style.height=photo.naturalHeight+'px';photo.style.transform=`translate(${px-photo.naturalWidth*scale/2}px,${py-photo.naturalHeight*scale/2}px) scale(${scale})`;document.querySelector('#zoom-value').textContent=Math.round(scale*100)+'%';stage.dataset.scale=scale;stage.dataset.pan=`${Math.round(px)},${Math.round(py)}`}
function reset(){if(!photo.naturalWidth)return;fit=Math.min((stage.clientWidth-24)/photo.naturalWidth,(stage.clientHeight-24)/photo.naturalHeight);scale=fit;px=0;py=0;paint()}
function zoom(factor,x=stage.clientWidth/2,y=stage.clientHeight/2){const previous=scale;scale=Math.max(fit*.25,Math.min(8,scale*factor));const cx=x-stage.clientWidth/2,cy=y-stage.clientHeight/2;px=cx-(cx-px)*scale/previous;py=cy-(cy-py)*scale/previous;paint()}
function openImage(id){lastFocus=document.activeElement;current=id;viewer.hidden=false;viewer.classList.toggle('no-info',MODE==='b');document.body.style.overflow='hidden';showImage();viewer.querySelector('#close').focus();}
function showImage(){const r=records.find(r=>r.id===current);const i=visible.findIndex(x=>x.id===current);document.querySelector('.vname').textContent=`@style_neco_e${String(r.epoch).padStart(6,'0')}_0${r.prompt}.png`;document.querySelector('.counter').textContent=`${i+1} / ${visible.length}`;document.querySelector('#prev').disabled=i<=0;document.querySelector('#next').disabled=i>=visible.length-1;photo.onload=reset;photo.src=r.asset.src;photo.alt=`${label(r)} 原比例大图`;if(photo.complete)requestAnimationFrame(reset);document.querySelector('#facts').innerHTML=`<div><small>尺寸</small><b>${r.asset.width} × ${r.asset.height}</b></div><div><small>轮次 / 步数</small><b>${r.epoch} / ${r.epoch*100}</b></div><div><small>提示词组</small><b>Prompt ${r.prompt+1}</b></div><div><small>Seed</small><b>${r.seed}</b></div><div><small>Steps</small><b>28</b></div><div><small>CFG</small><b>4.0</b></div>`;document.querySelector('#prompt-text').textContent=['character study, white hair, red and black outfit, clean background, full body, illustration','character study, neon yellow outfit, white hair, grey background, illustration','mechanical wings, character study, wide composition, clean background, illustration'][r.prompt];document.querySelector('.file-text').textContent=r.asset.original;document.querySelectorAll('.filmstrip').forEach(f=>f.innerHTML=visible.map(x=>`<button data-film="${x.id}" class="${x.id===current?'current':''}" aria-label="切换到 ${label(x)}"><img src="${x.asset.src}" alt="${label(x)}"></button>`).join(''));document.querySelector('#info').setAttribute('aria-expanded',!viewer.classList.contains('no-info'))}
function close(){viewer.hidden=true;document.body.style.overflow='';lastFocus?.focus()}
function move(delta){const index=visible.findIndex(x=>x.id===current),r=visible[index+delta];if(r){current=r.id;showImage()}}
stage.addEventListener('wheel',e=>{e.preventDefault();e.stopPropagation();const rect=stage.getBoundingClientRect();zoom(Math.exp(-Math.max(-120,Math.min(120,e.deltaY))*.002),e.clientX-rect.left,e.clientY-rect.top)},{passive:false});
const pointers=new Map();let pinch=null;
stage.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});stage.setPointerCapture(e.pointerId);stage.classList.add('dragging');if(pointers.size===1)drag={x:e.clientX,y:e.clientY,px,py};if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y)}}});
stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y),r=stage.getBoundingClientRect();if(pinch)zoom(distance/pinch.distance,(a.x+b.x)/2-r.left,(a.y+b.y)/2-r.top);pinch={distance}}else if(drag){px=drag.px+e.clientX-drag.x;py=drag.py+e.clientY-drag.y;paint()}});
function endPointer(e){pointers.delete(e.pointerId);pinch=null;drag=null;if(!pointers.size)stage.classList.remove('dragging');else{const p=[...pointers.values()][0];drag={x:p.x,y:p.y,px,py}}}stage.addEventListener('pointerup',endPointer);stage.addEventListener('pointercancel',endPointer);stage.addEventListener('dblclick',reset);
document.querySelector('#close').onclick=close;document.querySelector('#prev').onclick=()=>move(-1);document.querySelector('#next').onclick=()=>move(1);document.querySelector('#fit').onclick=reset;document.querySelector('#actual').onclick=()=>{scale=1;px=py=0;paint()};document.querySelector('#plus').onclick=()=>zoom(1.25);document.querySelector('#minus').onclick=()=>zoom(.8);
document.querySelector('#info').onclick=()=>{viewer.classList.toggle('no-info');document.querySelector('#info').setAttribute('aria-expanded',!viewer.classList.contains('no-info'));requestAnimationFrame(reset)};
document.querySelector('#download').onclick=()=>{const r=records.find(x=>x.id===current),a=document.createElement('a');a.href=r.asset.src;a.download=r.asset.original.replace('.png','-prototype.jpg');a.click()};
document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#prompt-text').textContent);toast('提示词已复制')}catch{toast('浏览器限制复制；可选中提示词手动复制')}};
document.addEventListener('click',e=>{const f=e.target.closest('[data-film]');if(f){current=Number(f.dataset.film);showImage()}});
document.addEventListener('keydown',e=>{if(viewer.hidden)return;if(e.key==='Escape')close();if(e.target.matches('input,textarea'))return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}if(e.key==='0')reset();if(e.key==='+'||e.key==='=')zoom(1.25);if(e.key==='-')zoom(.8);if(e.key==='Tab'){const list=[...viewer.querySelectorAll('button:not([disabled])')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});
observer=new ResizeObserver(()=>{if(!viewer.hidden)reset()});observer.observe(stage);window.addEventListener('resize',()=>{if(MODE==='c')render()});
let toastTimer;function toast(text){const el=document.querySelector('.toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,2600)}
render();
if(MODE==='a')document.querySelector('#density').value=108;
'''

HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__ · 样例页原型</title><style>__CSS__</style></head><body class="__MODE__">
<header class="top"><span class="wordmark"><i class="brand-dot"></i>ANIMA</span><span class="job">当前任务　@style_neco</span><span class="prototype">__TITLE__ / 交互原型</span></header>
<nav class="tabs" aria-label="项目页面"><span>配置</span><span>数据集</span><span>控制台</span><span class="current">样例</span><span>模型</span><span>环境</span></nav>
<div class="toolbar"><h1>样例</h1><small id="count"></small><div class="spacer"></div><input id="search" type="search" placeholder="搜索文件名或轮次…" aria-label="搜索样例"><select id="sort" aria-label="排列顺序"><option value="new">最新轮次优先</option><option value="old">最早轮次优先</option></select><label class="density">缩略图<input id="density" type="range" min="90" max="190" value="128" aria-label="缩略图尺寸"></label><button id="fill" style="display:__FILL__">完整缩略图</button><button id="select">多选</button><button id="refresh" class="icon" aria-label="刷新图库" data-icon="refresh"></button></div>
<div class="filters" aria-label="提示词分组"><button class="active" data-filter="-1">全部 36</button><button data-filter="0">Prompt 1</button><button data-filter="1">Prompt 2</button><button data-filter="2">Prompt 3</button><span class="hint">__HINT__</span></div>
<main aria-label="样例图库"><div class="gallery-layout"></div></main><footer class="footer"><span id="selection">点击查看 · Ctrl 多选</span><span class="right">演示数据与参数 · 图片来自本地样例</span></footer>
<section class="viewer" role="dialog" aria-modal="true" aria-label="图片详情" hidden><header class="vhead"><button id="close" class="icon" aria-label="关闭详情" data-icon="close"></button><span class="vname"></span><span class="grow"></span><button id="prev" class="icon" aria-label="上一张" data-icon="left"></button><span class="counter"></span><button id="next" class="icon" aria-label="下一张" data-icon="right"></button><button id="download" class="icon" aria-label="下载图片" data-icon="download"></button><button id="info" aria-label="显示或隐藏参数" aria-expanded="true">参数</button></header><div class="vbody"><div class="stage-wrap"><div class="stage" aria-label="图片画布，可滚轮缩放和拖动"><img alt="样例大图" draggable="false"></div><span class="zoom-hint">滚轮缩放 · 拖动平移 · 双击适应</span><div class="zoom-bar"><button id="minus" class="icon" aria-label="缩小">−</button><output id="zoom-value" class="zoom-value">100%</output><button id="plus" class="icon" aria-label="放大">＋</button><button id="fit">适应窗口</button><button id="actual">1:1</button></div></div><aside class="inspector"><h2>图片参数</h2><small>当前图片 / 演示参数</small><h3>生成信息</h3><div id="facts" class="facts"></div><h3>正向提示词</h3><p id="prompt-text" class="prompt-text"></p><button id="copy">复制提示词</button><h3>负向提示词</h3><p class="prompt-text">low quality, blurry, artifacts</p><h3>原始文件</h3><p class="file-text"></p><p class="note">此区域独立滚动。<br>切图时重置为适应窗口；折叠参数可扩大画布。<br><br>演示参数用于查看排版，未读取真实生成元数据。</p></aside><div class="filmstrip" aria-label="图片缩略导航"></div></div>__FILM__</section>
<div class="toast" role="status" hidden></div><script>__JS__</script></body></html>'''

titles = ['A 原比例密铺', 'B 紧凑联系表', 'C 轮次对照矩阵']
for mode, title in zip('abc', titles):
    html = HTML.replace('__CSS__', CSS).replace('__MODE__', mode).replace('__TITLE__', title)
    html = html.replace('__FILL__', 'inline-block' if mode == 'b' else 'none')
    html = html.replace('__HINT__', {'a':'原比例 · 5 px 图间距','b':'等格密排','c':'行：轮次 / 列：提示词'}[mode])
    html = html.replace('__FILM__', '<div class="filmstrip" aria-label="底部缩略导航"></div>' if mode == 'b' else '')
    # B has a bottom filmstrip; C has a left rail. A needs neither.
    if mode != 'c':
        html = html.replace('<div class="filmstrip" aria-label="图片缩略导航"></div>', '')
    html = html.replace('__JS__', JS.replace('__ASSETS__', json.dumps(assets)).replace('__MODE__', json.dumps(mode)))
    (OUT / f'dir-{"abc".index(mode)+1}.html').write_text(html, encoding='utf-8')
    if mode == 'a':
        (OUT / 'dir-1-v2.html').write_text(html.replace('A 原比例密铺', 'A 原比例密铺 v2'), encoding='utf-8')

print('Built three standalone prototypes:', OUT)
